let data = items.map(i => i.json);

// ---------- CNC definitions ----------
const CNC_LABELS = {
  A: "Angel",
  D: "Deformed",
  DP: "Deep",
  LG: "Large",
  LN: "Long",
  M: "Missing piece",
  N: "Non-disjointed thigh",
  OC: "Off centre",
  SH: "Short",
  SM: "Small",
  T: "Tip",
  TR: "Trim",
  UC: "Uncut",
  X: "Extra piece"
};

// ---------- OQI definitions ----------
const OQI_LABELS = {
  SKL: "Split keel",
  BW: "Broken wing",
  BD: "Broken drum",
  BRR: "Broken rib",
  WT: "Wing tip missing",
  BR: "Bruises",
  DD: "Disease dermatitis",
  DB: "Disease blister",
  DO: "Disease others",
  SB: "Stain bile",
  SI: "Stain ingesta",
  FEC: "Fecal",
  TE: "Skin tear",
  KT: "Knife trims",
  LHK: "Long hock",
  SHK: "Short hock",
  BT: "Broken thigh",
  LUN: "Lungs",
  HEA: "Heart",
  LIV: "Liver",
  GIZ: "Gizzard",
  SPL: "Spleen",
  WIN: "Windpipe",
  CR: "Crop",
  GAL: "Gall bladder",
  INT: "Intestine",
  CLO: "Cloaca",
  FEA: "Feathers",
  NEC: "Necks",
  CUT: "Cut",
  F: "Fat"
};

const CNC_CODES = new Set([
  "A","D","DP","LG","LN","M","N","OC","SH","SM","T","TR","UC","X"
]);

const OQI_CODES = new Set([
  "SKL","BW","BD","BRR","WT","BR","DD","DB","DO","SB","SI","FEC","TE","KT",
  "LHK","SHK","BT",
  "LUN","HEA","LIV","GIZ","SPL","WIN","CR","GAL","INT","CLO",
  "FEA","NEC","CUT","F"
]);

function parseCodes(str) {
  if (!str) return [];

  const normalized = String(str)
    .toUpperCase()
    .replace(/,/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  const matches = normalized.match(/\d+\s*[A-Z]+/g);
  if (!matches) return [];

  return matches.map(v => {
    const qty = parseInt(v, 10);
    const code = v.replace(/\d+/g, "").trim().toUpperCase();
    return { qty: isNaN(qty) ? 0 : qty, code };
  });
}

function initCut() {
  return { defects: {} };
}

function addDefect(cut, qty, label) {
  cut.defects[label] = (cut.defects[label] || 0) + qty;
}

function processCNC(cut, value) {
  for (const { qty, code } of parseCodes(value)) {
    if (!CNC_CODES.has(code)) continue;
    addDefect(cut, qty, CNC_LABELS[code] || code);
  }
}

function processOQI(cut, value) {
  for (const { qty, code } of parseCodes(value)) {
    if (!OQI_CODES.has(code)) continue;
    addDefect(cut, qty, OQI_LABELS[code] || code);
  }
}

function formatDateLong(dateStr) {
  if (!dateStr) return "N/A";

  const d = new Date(dateStr);
  if (isNaN(d)) return dateStr;

  const months = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
  ];

  return `${d.getDate()} ${months[d.getMonth()]} ${d.getFullYear()}`;
}

function formatDateForFile(dateStr) {
  if (!dateStr) return "Unknown-Date";

  const d = new Date(dateStr);
  if (isNaN(d)) {
    return String(dateStr)
      .trim()
      .replace(/[^\w-]+/g, "-")
      .replace(/-+/g, "-")
      .replace(/^-|-$/g, "");
  }

  const day = d.getDate();
  const monthNames = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
  ];
  const month = monthNames[d.getMonth()];
  const year = d.getFullYear();

  return `${day}-${month}-${year}`;
}

function escapeHtml(str) {
  return String(str ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function defectsToSortedArray(defects) {
  return Object.entries(defects)
    .map(([name, qty]) => ({ name, qty }))
    .sort((a, b) => b.qty - a.qty || a.name.localeCompare(b.name));
}

function totalFromDefects(defects) {
  return Object.values(defects).reduce((a, b) => a + b, 0);
}

function formatMainDefects(defects) {
  const arr = defectsToSortedArray(defects);
  if (!arr.length) return "-";
  return arr.map(x => `${x.name} ${x.qty}`).join(", ");
}

function renderCutTable(title, cuts) {
  const cutNames = ["Wing", "Drum", "Thigh", "Keel", "Rib"];

  const rows = cutNames.map(name => {
    const defects = cuts[name].defects;
    return `
      <tr>
        <td>${escapeHtml(name)}</td>
        <td class="num">${totalFromDefects(defects)}</td>
        <td>${escapeHtml(formatMainDefects(defects))}</td>
      </tr>
    `;
  }).join("");

  return `
    <div class="section">
      <div class="section-title">${escapeHtml(title)}</div>
      <table>
        <thead>
          <tr>
            <th style="width: 22%;">Cut Part</th>
            <th style="width: 14%;">Total</th>
            <th>Main Defects</th>
          </tr>
        </thead>
        <tbody>
          ${rows}
        </tbody>
      </table>
    </div>
  `;
}

// ---------- accumulators ----------
const cncCuts = {
  Wing: initCut(),
  Drum: initCut(),
  Thigh: initCut(),
  Keel: initCut(),
  Rib: initCut()
};

const oqiCuts = {
  Wing: initCut(),
  Drum: initCut(),
  Thigh: initCut(),
  Keel: initCut(),
  Rib: initCut()
};

let prodDate = "N/A";
const formKeySet = new Set();

let totalCNC = 0;
let oqiTotalCount = 0;

// ---------- process rows ----------
for (const row of data) {
  if (row.prod_date) prodDate = row.prod_date;

  const formKey = row.form_date || row.header_id || row.id;
  if (formKey) formKeySet.add(String(formKey));

  processCNC(cncCuts.Wing, row.wing_cnc);
  processCNC(cncCuts.Drum, row.drum_cnc);
  processCNC(cncCuts.Thigh, row.thigh_cnc);
  processCNC(cncCuts.Keel, row.keel_cnc);
  processCNC(cncCuts.Rib, row.rib_cnc);

  processOQI(oqiCuts.Wing, row.wing_qi);
  processOQI(oqiCuts.Drum, row.drum_qi);
  processOQI(oqiCuts.Thigh, row.thigh_qi);
  processOQI(oqiCuts.Keel, row.keel_qi);
  processOQI(oqiCuts.Rib, row.rib_qi);

  for (const key of ["wing_cnc", "drum_cnc", "thigh_cnc", "keel_cnc", "rib_cnc"]) {
    for (const { qty, code } of parseCodes(row[key])) {
      if (CNC_CODES.has(code)) totalCNC += qty;
    }
  }

  for (const key of ["wing_qi", "drum_qi", "thigh_qi", "keel_qi", "rib_qi"]) {
    for (const { qty, code } of parseCodes(row[key])) {
      if (OQI_CODES.has(code)) oqiTotalCount += qty;
    }
  }
}

// ---------- totals ----------
const formCount = formKeySet.size || 1;
const oqiTotal = oqiTotalCount;
const safeProdDate = formatDateForFile(prodDate);
const baseFileName = `ProductA-QC-Report-${safeProdDate}`;

// ---------- html ----------
const html = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>Product A - Cut Check Summary</title>
  <style>
    * { box-sizing: border-box; }

    body {
      margin: 0;
      padding: 28px;
      font-family: Arial, Helvetica, sans-serif;
      color: #111827;
      background: #ffffff;
    }

    .page {
      width: 100%;
      max-width: 1100px;
      margin: 0 auto;
    }

    .title {
      font-size: 30px;
      font-weight: 700;
      margin-bottom: 16px;
      letter-spacing: 0.2px;
    }

    .meta {
      margin-bottom: 22px;
      line-height: 1.8;
      font-size: 16px;
    }

    .summary-box {
      border: 1px solid #d1d5db;
      border-radius: 10px;
      padding: 0;
      overflow: hidden;
      margin-bottom: 26px;
    }

    .summary-header {
      background: #f3f4f6;
      padding: 12px 16px;
      font-size: 18px;
      font-weight: 700;
      border-bottom: 1px solid #d1d5db;
    }

    .section {
      margin-top: 24px;
      margin-bottom: 26px;
    }

    .section-title {
      font-size: 20px;
      font-weight: 800;
      margin-bottom: 10px;
    }

    table {
      width: 100%;
      border-collapse: collapse;
      table-layout: fixed;
      font-size: 15px;
    }

    th, td {
      border: 1px solid #d1d5db;
      padding: 10px 12px;
      vertical-align: top;
      word-wrap: break-word;
    }

    th {
      background: #f9fafb;
      text-align: left;
      font-weight: 700;
    }

    td.num {
      text-align: right;
      font-weight: 700;
      white-space: nowrap;
    }

  </style>
</head>
<body>
  <div class="page">
    <div class="title">Product A - Cut Check Summary</div>

    <div class="meta">
      <div><b>Production Date:</b> ${escapeHtml(formatDateLong(prodDate))}</div>
      <div><b>Forms Count:</b> ${formCount}</div>
    </div>

    <div class="summary-box">
      <div class="summary-header">Overall Summary</div>
      <table>
        <thead>
          <tr>
            <th style="width: 28%;">Metric</th>
            <th style="width: 22%;">CNC</th>
            <th style="width: 22%;">OQI</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td>Total</td>
            <td class="num">${totalCNC}</td>
            <td class="num">${oqiTotal}</td>
          </tr>
        </tbody>
      </table>
    </div>

    ${renderCutTable("CNC by Cut Part", cncCuts)}
    ${renderCutTable("OQI by Cut Part", oqiCuts)}

  </div>
</body>
</html>
`;

return [{
  json: {
    prod_date: prodDate,
    form_count: formCount,
    total_cnc: totalCNC,
    total_oqi: oqiTotal,
    pdf_file_name: `${baseFileName}.pdf`,
    html_file_name: `${baseFileName}.html`
  },
  binary: {
    html: {
      data: Buffer.from(html).toString("base64"),
      mimeType: "text/html",
      fileName: "index.html"
    }
  }
}];

const rawTs = $json.timestamp;

// Take only the local date part from the timestamp string
const datePart = String(rawTs).slice(0, 10); // e.g. 2026-03-12

if (!/^\d{4}-\d{2}-\d{2}$/.test(datePart)) {
  throw new Error(`Invalid timestamp received: ${rawTs}`);
}

// Create a safe date from the date part only
const reportDate = new Date(datePart + "T00:00:00");
reportDate.setDate(reportDate.getDate() - 1);

function pad(n) {
  return String(n).padStart(2, '0');
}

function fmtDate(d) {
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

return [
  {
    json: {
      trigger_timestamp: rawTs,
      report_prod_date: fmtDate(reportDate)
    }
  }
];

